    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Electric Studio variant: dark base, electric blue accents
           Data-forward technical aesthetic for JS engineers
           =========================================== */
        :root {
            --bg-dark: #080c14;
            --bg-card: #0f1623;
            --bg-panel: #141d2e;
            --accent-blue: #3d7eff;
            --accent-bright: #5b96ff;
            --accent-gold: #f5c842;
            --accent-green: #36d399;
            --accent-red: #ff4757;
            --accent-orange: #ff6b35;
            --text-primary: #eef2ff;
            --text-secondary: #8fa3c8;
            --text-muted: #4a5f82;
            --border: rgba(61, 126, 255, 0.15);
            --border-bright: rgba(61, 126, 255, 0.4);
            --glow: rgba(61, 126, 255, 0.25);

            --font-display: 'Manrope', sans-serif;
            --font-mono: 'JetBrains Mono', monospace;

            /* Typography — clamp() for responsive scaling */
            --title-size: clamp(1.6rem, 4.5vw, 3.8rem);
            --h2-size: clamp(1.2rem, 2.8vw, 2.2rem);
            --h3-size: clamp(0.9rem, 1.8vw, 1.4rem);
            --body-size: clamp(0.72rem, 1.2vw, 1rem);
            --small-size: clamp(0.62rem, 0.9vw, 0.8rem);
            --mono-size: clamp(0.65rem, 1vw, 0.85rem);

            /* Spacing — clamp() for responsive */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.6rem, 1.5vw, 1.5rem);
            --element-gap: clamp(0.3rem, 0.8vw, 0.8rem);

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.65s;
        }

        /* ===========================================
           BASE RESET
           =========================================== */
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: var(--font-display);
            background: var(--bg-dark);
            color: var(--text-primary);
            overflow: hidden;
        }

        /* ===========================================
           VIEWPORT BASE CSS (mandatory inclusion)
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }

        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }

        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           SHARED SLIDE BACKGROUND
           =========================================== */
        .slide-bg {
            position: absolute;
            inset: 0;
            background: var(--bg-dark);
            z-index: 0;
        }

        .slide-bg::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(61, 126, 255, 0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(61, 126, 255, 0.03) 1px, transparent 1px);
            background-size: 60px 60px;
        }

        .slide > *:not(.slide-bg) {
            position: relative;
            z-index: 1;
        }

        /* ===========================================
           REVEAL ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(24px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal { opacity: 1; transform: translateY(0); }

        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        .reveal-left {
            opacity: 0;
            transform: translateX(calc(-1 * clamp(20px, 3vw, 40px)));
            transition: opacity 0.6s var(--ease-out-expo), transform 0.6s var(--ease-out-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }

        /* ===========================================
           SLIDE HEADER (shared across all slides)
           =========================================== */
        .slide-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: clamp(0.75rem, 2vw, 1.5rem) var(--slide-padding);
            border-bottom: 1px solid var(--border);
            flex-shrink: 0;
        }

        .slide-brand {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-blue);
            letter-spacing: 0.12em;
            text-transform: uppercase;
            opacity: 0.85;
        }

        .slide-counter {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
        }

        /* ===========================================
           SLIDE FOOTER
           =========================================== */
        .slide-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: clamp(0.5rem, 1.5vw, 1rem) var(--slide-padding);
            border-top: 1px solid var(--border);
            flex-shrink: 0;
        }

        .footer-source {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
        }

        .footer-tag {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            background: rgba(61, 126, 255, 0.08);
            border: 1px solid var(--border);
            padding: 0.15em 0.6em;
            border-radius: 3px;
        }

        /* ===========================================
           SLIDE 1: TITLE COVER
           =========================================== */
        #slide-title {
            background: var(--bg-dark);
        }

        #slide-title .slide-bg::after {
            content: '';
            position: absolute;
            top: -20%;
            right: -10%;
            width: min(60vw, 700px);
            height: min(60vw, 700px);
            background: radial-gradient(circle, rgba(61, 126, 255, 0.12) 0%, transparent 65%);
            border-radius: 50%;
        }

        .title-main {
            padding: var(--slide-padding);
            display: flex;
            flex-direction: column;
            gap: var(--content-gap);
            flex: 1;
            justify-content: center;
        }

        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-blue);
            letter-spacing: 0.15em;
            text-transform: uppercase;
            display: flex;
            align-items: center;
            gap: 0.6em;
        }

        .title-eyebrow::before {
            content: '';
            display: inline-block;
            width: clamp(16px, 2.5vw, 28px);
            height: 1px;
            background: var(--accent-blue);
        }

        .title-h1 {
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            color: var(--text-primary);
            max-width: min(70vw, 900px);
        }

        .title-h1 span {
            color: var(--accent-blue);
        }

        .title-meta {
            display: flex;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: center;
            flex-wrap: wrap;
            margin-top: clamp(0.5rem, 1vw, 1rem);
        }

        .meta-badge {
            background: rgba(61, 126, 255, 0.1);
            border: 1px solid var(--border-bright);
            border-radius: 4px;
            padding: 0.35em 0.9em;
            font-size: var(--small-size);
            color: var(--accent-bright);
            font-family: var(--font-mono);
        }

        .title-stat-row {
            display: flex;
            gap: clamp(1.5rem, 3vw, 3rem);
            margin-top: clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .title-stat {
            display: flex;
            flex-direction: column;
            gap: 0.2em;
        }

        .title-stat-num {
            font-size: clamp(1.5rem, 3vw, 2.5rem);
            font-weight: 800;
            color: var(--accent-gold);
            line-height: 1;
        }

        .title-stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           SLIDE 2: OVERALL TOP 10
           =========================================== */
        .chart-container {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vh, 0.7rem);
            width: 100%;
            max-height: min(72vh, 560px);
            overflow: hidden;
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            min-height: 0;
        }

        .bar-rank {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            width: clamp(1.2rem, 2vw, 1.8rem);
            text-align: right;
            flex-shrink: 0;
        }

        .bar-name {
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
            width: clamp(80px, 12vw, 140px);
            flex-shrink: 0;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .bar-track {
            flex: 1;
            height: clamp(18px, 2.5vh, 32px);
            background: rgba(255,255,255,0.04);
            border-radius: 3px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 3px;
            width: 0;
            transition: width 1s var(--ease-out-expo);
            position: relative;
        }

        .slide.visible .bar-fill {
            width: var(--bar-width);
        }

        .bar-fill.rank-1 { background: linear-gradient(90deg, var(--accent-blue), var(--accent-bright)); }
        .bar-fill.rank-2 { background: linear-gradient(90deg, #2d6bea, #4a80f0); }
        .bar-fill.rank-3 { background: linear-gradient(90deg, #1e5cc4, #3570e0); }
        .bar-fill.other  { background: linear-gradient(90deg, #1a3d7a, #2a5298); }

