<script>
    /* ===========================================
       SLIDE PRESENTATION CONTROLLER
       Handles navigation, animations, progress, nav dots
       =========================================== */
    class SlidePresentation {
        constructor() {
            this.slides = document.querySelectorAll('.slide');
            this.currentIndex = 0;
            this.isScrolling = false;

            this.setupIntersectionObserver();
            this.setupKeyboardNav();
            this.setupTouchNav();
            this.setupWheelNav();
            this.setupProgressBar();
            this.setupNavDots();

            // Activate first slide immediately
            this.slides[0].classList.add('visible');
        }

        setupIntersectionObserver() {
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                        const idx = Array.from(this.slides).indexOf(entry.target);
                        this.currentIndex = idx;
                        this.updateProgress(idx);
                        this.updateNavDots(idx);
                    }
                });
            }, { threshold: 0.5 });

            this.slides.forEach(slide => observer.observe(slide));
        }

        goToSlide(index) {
            if (index < 0 || index >= this.slides.length) return;
            this.slides[index].scrollIntoView({ behavior: 'smooth' });
        }

        setupKeyboardNav() {
            document.addEventListener('keydown', (e) => {
                switch(e.key) {
                    case 'ArrowDown':
                    case 'ArrowRight':
                    case ' ':
                    case 'PageDown':
                        e.preventDefault();
                        this.goToSlide(this.currentIndex + 1);
                        break;
                    case 'ArrowUp':
                    case 'ArrowLeft':
                    case 'PageUp':
                        e.preventDefault();
                        this.goToSlide(this.currentIndex - 1);
                        break;
                    case 'Home':
                        e.preventDefault();
                        this.goToSlide(0);
                        break;
                    case 'End':
                        e.preventDefault();
                        this.goToSlide(this.slides.length - 1);
                        break;
                }
            });
        }

        setupTouchNav() {
            let touchStartY = 0;
            let touchStartX = 0;

            document.addEventListener('touchstart', (e) => {
                touchStartY = e.touches[0].clientY;
                touchStartX = e.touches[0].clientX;
            }, { passive: true });

            document.addEventListener('touchend', (e) => {
                const dy = touchStartY - e.changedTouches[0].clientY;
                const dx = touchStartX - e.changedTouches[0].clientX;
                const threshold = 50;

                if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > threshold) {
                    this.goToSlide(dy > 0 ? this.currentIndex + 1 : this.currentIndex - 1);
                }
            }, { passive: true });
        }

        setupWheelNav() {
            let lastWheel = 0;
            document.addEventListener('wheel', (e) => {
                const now = Date.now();
                if (now - lastWheel < 800) return;
                lastWheel = now;
                this.goToSlide(e.deltaY > 0 ? this.currentIndex + 1 : this.currentIndex - 1);
            }, { passive: true });
        }

        setupProgressBar() {
            this.progressBar = document.getElementById('progressBar');
        }

        updateProgress(index) {
            if (!this.progressBar) return;
            const pct = ((index) / (this.slides.length - 1)) * 100;
            this.progressBar.style.width = pct + '%';
        }

        setupNavDots() {
            const nav = document.getElementById('navDots');
            if (!nav) return;

            this.slides.forEach((_, i) => {
                const dot = document.createElement('button');
                dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
                dot.addEventListener('click', () => this.goToSlide(i));
                nav.appendChild(dot);
            });
        }

        updateNavDots(index) {
            const dots = document.querySelectorAll('.nav-dot');
            dots.forEach((dot, i) => {
                dot.classList.toggle('active', i === index);
            });
        }
    }

    /* Initialize when DOM is ready */
    document.addEventListener('DOMContentLoaded', () => {
        new SlidePresentation();
    });

    /* Also handle bar chart animation delays for staggered bars */
    document.addEventListener('DOMContentLoaded', () => {
        const barRows = document.querySelectorAll('.bar-row');
        barRows.forEach((row, i) => {
            const fill = row.querySelector('.bar-fill');
            if (fill) {
                fill.style.transitionDelay = (i * 0.07) + 's';
            }
        });

        const fwRows = document.querySelectorAll('.fw-row');
        fwRows.forEach((row, i) => {
            const fill = row.querySelector('.fw-fill');
            if (fill) {
                fill.style.transitionDelay = (i * 0.12) + 's';
            }
        });
    });
</script>
